const FOLDER_FIELDS: FolderFieldDescriptor[] = [
    { field: 'projectFolder', group: 'root', label: 'Project folder' },
    { field: 'workingFolder', group: 'live', label: 'Working folder' },
    { field: 'diagramsFolder', group: 'live', label: 'Diagrams folder' },
