}

const PROJECT_CONFIG_GROUPS: ProjectConfigGroup[] = [
    {
        description: 'Where MDÂ² reads and writes this project\'s files. Every folder except the project folder is relative to it.',
        id: 'project-folders',
        keys: [
            'project.projectFolder',
